package dev.apkproject.app

/**
 * The permissions each platform method requires, from the Android SDK's own `RequiresPermission`
 * annotations (`platform-permissions.tsv`, generated by `scripts/privacy/platform_permissions.py`
 * from platform 35's `data/annotations.zip`). The privacy map uses it to tell, per API rather than per
 * kind of data, whether the manifest requests what a source needs.
 */
object PlatformPermissions {
    /**
     * One overload's requirement: [anyOf] (one of them; `value` annotations too) or [allOf], the API
     * levels it applies to ([upTo]: the last one, or null when it applies to every level), and whether
     * it applies only to part of the result ([conditional]: the call works without it).
     */
    class Requirement(val anyOf: List<String>, val allOf: List<String>, val upTo: Int?, val conditional: Boolean)

    private val table: Map<String, List<Requirement>> by lazy { load() }

    private fun load(): Map<String, List<Requirement>> {
        val text = PlatformPermissions::class.java.getResourceAsStream("/dev/apkproject/app/platform-permissions.tsv")?.use { it.readBytes().toString(Charsets.UTF_8) } ?: return emptyMap()
        val out = HashMap<String, MutableList<Requirement>>()
        for (line in text.lineSequence()) {
            if (line.isBlank() || line.startsWith("#")) continue
            val c = line.split('\t')
            if (c.size < 7) continue
            val perms = c[4].split(',').filter { it.isNotBlank() && ' ' !in it }
            val upTo = c[5].takeIf { it.startsWith("..") }?.removePrefix("..")?.toIntOrNull()
            val req = if (c[3] == "allOf") Requirement(emptyList(), perms, upTo, c[6] == "true") else Requirement(perms, emptyList(), upTo, c[6] == "true")
            out.getOrPut("${c[0]}.${c[1]}") { ArrayList() } += req
        }
        return out
    }

    /** Whether the table knows [api] (`android.location.LocationManager.getLastKnownLocation`, any overload). */
    fun knows(api: String): Boolean = api in table

    /**
     * Permissions a call of [api] needs on every Android level: the union over its overloads, leaving out
     * requirements limited to older levels (`GET_ACCOUNTS` up to API 22: newer levels run the call
     * without it) and conditional ones (the call works without them; what they withhold is
     * [SourceRuntime]'s business). Any one of them is taken as enough, as the overload called is not
     * known and an `allOf` of one overload may be an `anyOf` of another.
     */
    fun permissions(api: String): List<String> =
        table[api].orEmpty().filter { r -> !r.conditional && r.upTo == null }.flatMap { it.anyOf + it.allOf }.distinct().sorted()
}
